class LinkedList():
    def __init__(self):
        self.length = 0
        self.head = None
        self.tail = None

    def pop(self, index):
        if index == 0:
            val = self.head.val
            if self.length < 2:
                self.head = None
                self.tail = None
            else:
                self.head = self.head.next
            self.length -= 1
            return val
        node = self.head
        while index > 1:
            node = node.next
            index -= 1
        val = node.next.val
        node.next = node.next.next
        self.length -= 1
        return val

    def append(self, val):
        node = Node(val)
        if self.length == 0:
            self.head = node
            self.tail = node
        else:
            prev = self.tail.next
            prev.next = node
            self.tail.next = node
        self.length += 1

class Node():
    def __init__(self, val=None, next=None):
        self.val = val
        self.next = next
    def __str__(self):
